const items = $input.all();
if (!items.length) return [{ json: { empty: true } }];
const lines = items.slice(0, 25).map((i) => {
  const j = i.json;
  return `From: ${j.from || ''} | Subject: ${j.subject || ''} | Snippet: ${String(j.snippet || '').slice(0, 200)}`;
});
return [{ json: { empty: false, blob: lines.join('\n') } }];

if ($('Pack Subjects').item.json.empty) return [];
const raw = $json.choices?.[0]?.message?.content || '{}';
let c;
try { c = JSON.parse(raw); } catch { return []; }
if (c.skip) return [];
const body = String(c.alert_body || c.whatsapp_body || '').slice(0, 3500);
if (!body.trim()) return [];
return [{ json: { alert_body: body } }];
